matrix_style:
QFrame#ProgressPanel,
QFrame#StartupSplashProgressPanel {
    background: #151D1A;
    border: 1px solid #00FF7A;
}
QLabel#ProgressPanelTitle {
    color: #E8F0EC;
    font-weight: 700;
}
QLabel#ProgressPanelDetail {
    color: #7A9A88;
}
QProgressBar {
    background: #151D1A;
    border: 1px solid #00FF7A;
    height: 8px;
    text-align: center;
}
QProgressBar::chunk {
    background: #00FF7A;
}

light_style:
QFrame#ProgressPanel,
QFrame#StartupSplashProgressPanel {
    background: #EEF2F6;
    border: 1px solid #1F6FEB;
}
QLabel#ProgressPanelTitle {
    color: #1D2733;
    font-weight: 700;
}
QLabel#ProgressPanelDetail {
    color: #52616F;
}
QProgressBar {
    background: #FFFFFF;
    border: 1px solid #1F6FEB;
    height: 8px;
    text-align: center;
}
QProgressBar::chunk {
    background: #1B8F45;
}
